function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree has at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1000) return 'The tree has at most 1000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each node value is a whole number from 1 to 10^6.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  return null;
}

