function getLonelyNodes(root) {
  // Record every node's parent with a BFS, then count each parent's children.
  const parentOf = new Map();
  const order = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    order.push(node);
    for (const child of [node.left, node.right]) {
      if (child) {
        parentOf.set(child, node);
        queue.push(child);
      }
    }
  }
  const result = [];
  for (const node of order) {
    if (!parentOf.has(node)) continue;
    const parent = parentOf.get(node);
    const children = (parent.left ? 1 : 0) + (parent.right ? 1 : 0);
    if (children === 1) result.push(node.val);
  }
  return result;
}

