function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const count = size === 'large' ? 950 + pick(51) : 1 + pick(12);
  const top = size === 'large' ? 1000000 : rand() < 0.3 ? 3 : 1000000;
  const value = () => 1 + pick(top);
  // Small trees are sometimes chain-like, which makes many lonely nodes.
  const deep = rand() < 0.35;
  const nodes = [{ val: value(), left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: value(), left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
